sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float targetAspect;
uniform float position;
layout(color) uniform half4 barColor;
uniform float softness;
uniform float amount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float soft = max(softness, 0.5);
    float barH = max((size.y - size.x / targetAspect) * 0.5, 0.0) * amount;
    float barW = max((size.x - size.y * targetAspect) * 0.5, 0.0) * amount;
    float top = barH * (1.0 + position);
    float bottom = barH * (1.0 - position);
    float topM = 1.0 - smoothstep(top - soft, top, coord.y);
    float botM = smoothstep(size.y - bottom, size.y - bottom + soft, coord.y);
    float leftM = 1.0 - smoothstep(barW - soft, barW, coord.x);
    float rightM = smoothstep(size.x - barW, size.x - barW + soft, coord.x);
    float bars = max(max(topM, botM), max(leftM, rightM));
    float3 o = mix(s, float3(barColor.rgb), bars);
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), opacity);
}
